from pandas.core.dtypes.dtypes import CategoricalDtype
from pandas.core.dtypes.common import is_list_like
from pandas.core.dtypes.inference import is_categorical_dtype
from pandas.core.arrays.categorical import Categorical
from pandas import Series, Index, DataFrame
from pandas.core.indexes.base import Index
from pandas.core.arrays.integer import CategoricalDtype as CategoricalDtypeType
from pandas.api import types as ptypes
from pandas.core import common as com
from pandas.core.indexes.api import ensure_index
from pandas.core.arrays import Categorical as _Categorical, factorize, extract_array, recode_for_categories
from pandas.core.arrays.categorical import _get_codes_for_values
from pandas.core.algorithms import isin
from pandas.core.common import sanitize_array
from pandas.core.array_algos import isna
from pandas.core.indexers import coerce_indexer_dtype
from pandas import errors

def __init__(
        self,
        values,
        categories=None,
        ordered=None,
        dtype: CategoricalDtype | None = None,
        copy: bool = True,
    ) -> None:
        dtype = CategoricalDtype._from_values_or_dtype(
            values, categories, ordered, dtype
        )

        if not is_list_like(values):
            raise TypeError("Categorical input must be list-like")

        null_mask = np.array(False)

        vdtype = getattr(values, "dtype", None)
        if is_categorical_dtype(vdtype):
            if dtype.categories is None:
                dtype = CategoricalDtype(vdtype.categories, dtype.ordered)
        elif isinstance(values, range):
            values = ensure_index(values)
        elif not isinstance(values, (_Categorical, Series, Index)):
            values = com.convert_to_list_like(values)
            if isinstance(values, list) and len(values) == 0:
                values = np.array([], dtype=object)
            elif isinstance(values, np.ndarray):
                if values.ndim > 1:
                    raise NotImplementedError(
                        "> 1 ndim Categorical are not supported at this time"
                    )
                values = sanitize_array(values, None)
            else:
                arr = sanitize_array(values, None)
                null_mask = isna(arr)
                if null_mask.any():
                    arr_list = [values[idx] for idx in np.where(~null_mask)[0]]
                    if arr_list or arr.dtype == "object":
                        sanitize_dtype = None
                    else:
                        sanitize_dtype = arr.dtype
                    arr = sanitize_array(arr_list, None, dtype=sanitize_dtype)
                values = arr

        if dtype.categories is None:
            if isinstance(values.dtype, ptypes.ArrowDtype) and issubclass(
                values.dtype.type, CategoricalDtypeType
            ):
                if isinstance(values, Index):
                    arr = values._data._pa_array.combine_chunks()
                else:
                    arr = extract_array(values)._pa_array.combine_chunks()
                categories = arr.dictionary.to_pandas(types_mapper=ptypes.ArrowDtype)
                codes = arr.indices.to_numpy()
                dtype = CategoricalDtype(categories, values.dtype.pyarrow_dtype.ordered)
            else:
                if not isinstance(values, Index):
                    values = sanitize_array(values, None)
                try:
                    codes, categories = factorize(values, sort=True)
                except TypeError as err:
                    codes, categories = factorize(values, sort=False)
                    if dtype.ordered:
                        raise TypeError(
                            "'values' is not ordered, please "
                            "explicitly specify the categories order "
                            "by passing in a categories argument."
                        ) from err
                dtype = CategoricalDtype(categories, dtype.ordered)

        elif is_categorical_dtype(values.dtype):
            old_codes = extract_array(values)._codes
            codes = recode_for_categories(
                old_codes,
                values.dtype.categories,
                dtype.categories,
                copy=copy,
                warn=True,
            )

        else:
            codes = _get_codes_for_values(values, dtype.categories)

        if null_mask.any():
            full_codes = -np.ones(null_mask.shape, dtype=codes.dtype)
            full_codes[~null_mask] = codes
            codes = full_codes

        dtype = CategoricalDtype(ordered=False).update_dtype(dtype)
        arr = coerce_indexer_dtype(codes, dtype.categories)
        super().__init__(arr, dtype)

